insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A4', '2:30', '“What makes the longer calls longer for you?”', 'effective', 'Good open question', 3 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A5', '3:00', 'Jordan: “The new verification step keeps timing out.” Alex: “Let''s not make excuses.”', 'critical_miss', 'Dismisses the root cause the agent just named', 4 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A6', '4:00–6:00', 'Alex talks for about two minutes giving tips', 'clear_miss', 'Telling, not coaching; agent talk time collapses', 5 from public.scenarios where family = 'rec-coaching' and version = 'A';
